-- Новая программа тренировок: «Full body болгарские выпады» (12 тренировок).
--
-- Новые программы живут в program_templates (см. mergeTemplates в src/App.jsx).
-- Зашитые FOLDERS/PROGRAMS_MAP в src/programs.js НЕ трогаем: это запасной
-- вариант для первых четырёх программ, если база молчит.
--
-- key задан по правилу slugifyKey из App.jsx (латиница) и НЕ меняется никогда:
-- за него держатся profiles.program и префикс названий в workouts
-- («{key} — тренировка N»). Переименование программы — только display_name.

-- 1. Иконка и описание программы переезжают в базу.
--    Раньше жили в FOLDER_ICONS / FOLDER_DESCRIPTIONS в App.jsx, то есть каждая
--    новая программа требовала правки кода и выкладки. Программ будет много —
--    держим их данными, а не кодом. Зашитые словари остаются запасным вариантом
--    для первых четырёх ключей.
alter table program_templates add column if not exists icon        text;
alter table program_templates add column if not exists description text;

-- 2. Единственное упражнение, которого ещё не было в каталоге.
--    Остальные названия в структуре уже есть в EXERCISES (src/programs.js).
insert into catalog_exercises (name, muscle_group, equipment, type, hidden)
values ('Выпады назад с подставки', 'Ноги', 'Гантели', 'compound', false)
on conflict (name) do nothing;

-- 3. Сама программа. sort — в конец списка программ.
insert into program_templates (key, display_name, context, sort, hidden, icon, description, structure)
